mapper.sql:
WHERE h.deleted = 0

    AND h.status = #{forcedStatus}


    AND h.status = #{q.status}


    AND h.house_type = #{q.houseType}


    AND h.region LIKE CONCAT(#{q.region}, '%')


    AND h.price >= #{q.minPrice}


    AND h.price <= #{q.maxPrice}


    AND h.area >= #{q.minArea}


    AND h.area <= #{q.maxArea}


    AND (h.title LIKE CONCAT(#{q.keyword}, '%') OR h.community LIKE CONCAT(#{q.keyword}, '%'))


    AND h.rooms = #{q.rooms}

mapper.select:
SELECT h.id, h.title, h.house_type, h.status, h.community, h.region, h.price, h.area, h.rooms, h.bathrooms, h.floor, h.owner_id, h.created_at FROM house h
ORDER BY h.price ASC, h.id DESC ORDER BY h.price DESC, h.id DESC ORDER BY h.area ASC, h.id DESC ORDER BY h.area DESC, h.id DESC ORDER BY h.created_at DESC, h.id DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE house
SET status = #{target}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0
AND status IN

    #{s}
